import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"肌群概览","description":"认识全身的肌群","frontmatter":{"title":"肌群概览","description":"认识全身的肌群","date":"2026-05-29T00:00:00.000Z","category":"健康健身","tags":["力量训练"],"order":3},"headers":[],"relativePath":"articles/fitness/strength/overview.md","filePath":"articles/fitness/strength/overview.md","articleMeta":{"updated":"2026-05-29","words":833,"minutes":2}}`),a={name:`articles/fitness/strength/overview.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="一图看懂全身肌肉" tabindex="-1">一图看懂全身肌肉 <a class="header-anchor" href="#一图看懂全身肌肉" aria-label="Permalink to “一图看懂全身肌肉”">​</a></h2><p><img src="/images/IMG_1686260422.webp" alt="IMG_1686" width="1206" height="1614"></p><p><img src="/images/IMG_1687260422.webp" alt="IMG_1687" width="1206" height="1224"></p><p><img src="/images/IMG_1688260422.webp" alt="IMG_1688" width="1206" height="1619"></p><p><img src="/images/IMG_1689260422.webp" alt="IMG_1689" width="1206" height="1597"></p><p><img src="/images/IMG_1690260422.webp" alt="IMG_1690" width="1206" height="1602"></p><p><img src="/images/IMG_1691260422.webp" alt="IMG_1691" width="1206" height="1590"></p><p><img src="/images/IMG_1692260422.webp" alt="IMG_1692" width="1206" height="1597"></p><h2 id="锻炼肌肉是高质量人生的必修课" tabindex="-1">锻炼肌肉是高质量人生的必修课 <a class="header-anchor" href="#锻炼肌肉是高质量人生的必修课" aria-label="Permalink to “锻炼肌肉是高质量人生的必修课”">​</a></h2><p>人体肌肉随年龄增长发生结构和功能性退化，30-40岁达到峰值后，肌肉质量以每10年约3%-8%的速度递减，40岁后加速，50-60岁后每年递减1%-2%，70岁后流失显著，导致力量下降、代谢减慢及肌少症风险</p><p>健康是人生一切意义的<strong>唯一载体</strong>，而肌肉是维持身体健康的核心硬件：</p><ol><li><strong>代谢与慢病防御</strong>：肌肉是人体最大的代谢器官，肌肉量直接决定基础代谢率。充足的肌肉能高效消耗血糖、血脂，大幅降低 2 型糖尿病、高血压、高血脂等代谢类慢病的发病风险，从根源减少疾病对人生的消耗。</li><li><strong>骨骼与运动保护</strong>：肌肉是骨骼的 “天然护具”，强健的肌肉能稳定关节、缓冲外力冲击，预防中老年骨质疏松、骨折、腰颈劳损，避免因身体损伤丧失行动自由。</li><li><strong>对抗衰老的核心筹码</strong>：30 岁后人体肌肉量每年自然流失，肌少症是老年失能、生活质量崩塌的主要诱因。主动投资肌肉，就是提前储备「抗衰资本」，延长<strong>健康寿命</strong>（而非单纯生存寿命），让人生后半程依然拥有独立生活、体验世界的能力。</li></ol><p>年轻时打下的肌肉基础，中年只需低强度维持即可保有量能，老年的肌肉储备会直接决定生活自理能力、抗病能力。<strong>肉身是体验世间一切美好的唯一容器</strong>，爱护身体、投资肌肉，是对生命最本质的敬畏与负责。</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};